mapper.insert:
MERGE INTO TB_COURSE AS TG
USING ( SELECT #{courseSeq} AS COURSE_SEQ) AS SS ON (TG.COURSE_SEQ = SS.COURSE_SEQ)
WHEN NOT MATCHED THEN
INSERT (
TITLE
, CATEGORY_ID
, MAIN_IMG
, PRICE
, BADGE
, INTROD
, DISPLAY_YN
, CONTENT_DETAIL
)
VALUES(
#{title}
, #{categoryId}
, #{mainImg}
, #{price}
, #{badge}
, #{introd}
, #{displayYn}
, #{contentDetail}
)
WHEN MATCHED THEN
UPDATE
SET TITLE = #{title}
, CATEGORY_ID = #{categoryId}
, MAIN_IMG = #{mainImg}
, PRICE = #{price}
, BADGE = #{badge}
, INTROD = #{introd}
, DISPLAY_YN = #{displayYn}
, CONTENT_DETAIL = #{contentDetail}
;

    DECLARE @COURSE_SEQ INT
    SELECT @COURSE_SEQ = COURSE_SEQ
    FROM TB_COURSE
    WHERE COURSE_SEQ = #{courseSeq}

    IF @COURSE_SEQ IS NULL
    BEGIN
    SELECT IDENT_CURRENT('TB_COURSE')
    END
    ELSE
    BEGIN
    SELECT @COURSE_SEQ
    END

    MERGE INTO TB_COURSE_DETAIL AS TG
    USING (
            SELECT #{courseSeq}         AS COURSE_SEQ
                    , #{courseDtlSeq}   AS COURSE_DTL_SEQ
          ) AS SS ON (TG.COURSE_SEQ = SS.COURSE_SEQ AND TG.COURSE_DTL_SEQ = SS.COURSE_DTL_SEQ)
    WHEN NOT MATCHED  THEN
        INSERT ( COURSE_SEQ
                , UNIT_TITLE
                , DISPLAY_YN
                , SORT
                , FILE_SEQ
            )
        VALUES(
            #{courseSeq}
            , #{unitTitle}
            , #{displayYn}
            , #{sort}
            , #{fileSeq}
        )
    WHEN  MATCHED  THEN
            UPDATE
            SET   UNIT_TITLE = #{unitTitle}
                , DISPLAY_YN = #{displayYn}
                , SORT       = #{sort}
;

INSERT INTO TB_ADMIN
(
    ADM_ID
    , ADM_PWD
    , ADM_NAME
    , ADM_EMAIL
)
VALUES (
    #{admId}
    , #{admPwd}
    , #{admName}
    , #{admEmail}
)

